    13→export type TagSelectorProps<T extends string> = {
    14→  /** Label displayed above the tags */
    15→  label?: string;
    16→  /** Available tags to select from */
    17→  tags: readonly T[];
    18→  /** Currently selected tags */
    19→  selectedTags: T[];
    20→  /** Callback when selection changes */
    21→  onChange: (tags: T[]) => void;
    22→  /** Labels for each tag (key -> display label) */
    23→  tagLabels?: Record<T, string>;
    24→  /** Disabled state */
    25→  disabled?: boolean;
    26→  /** Additional CSS classes */
    27→  className?: string;
    28→};
    29→
    30→/**
    31→ * TagSelector Component
    32→ *
    33→ * Multi-select tag picker with toggle behavior.
    34→ * Tags wrap to multiple lines and have a pill-like appearance.
    35→ *
    36→ * @example
    37→ * ```tsx
    38→ * // Generic usage
    39→ * <TagSelector
    40→ *   label="Contexte de la journée"
    41→ *   tags={['work', 'exercise', 'social']}
    42→ *   selectedTags={selected}
    43→ *   onChange={setSelected}
    44→ *   tagLabels={{ work: 'Travail', exercise: 'Sport', social: 'Social' }}
    45→ * />
    46→ * ```
    47→ */
    48→export function TagSelector<T extends string>({
    49→  label,
    50→  tags,
    51→  selectedTags,
    52→  onChange,
    53→  tagLabels,
    54→  disabled = false,
    55→  className,
    56→}: TagSelectorProps<T>) {
    57→  const toggleTag = (tag: T) => {
    58→    if (disabled) return;
    59→
    60→    if (selectedTags.includes(tag)) {
    61→      onChange(selectedTags.filter((t) => t !== tag));
    62→    } else {
    63→      onChange([...selectedTags, tag]);
    64→    }
    65→  };
    66→
    67→  const getLabel = (tag: T): string => {
    68→    if (tagLabels && tag in tagLabels) {
    69→      return tagLabels[tag];
    70→    }
    71→    // Fallback: capitalize and replace underscores
    72→    return tag.replace(/_/g, " ").replace(/\b\w/g, (l) => l.toUpperCase());
    73→  };
    74→
    75→  return (
    76→    <div className={cn("flex flex-col gap-2", className)}>
    77→      {label && (
    78→        <span className="text-foreground text-sm font-medium">{label}</span>
    79→      )}
    80→      <div className="flex flex-wrap gap-2" role="group" aria-label={label}>
    81→        {tags.map((tag) => {
    82→          const isSelected = selectedTags.includes(tag);
    83→
    84→          return (
    85→            <button
    86→              key={tag}
    87→              type="button"
    88→              role="checkbox"
    89→              aria-checked={isSelected}
    90→              disabled={disabled}
    91→              onClick={() => toggleTag(tag)}
    92→              className={cn(
    93→                "rounded-full px-3 py-1.5 text-sm font-medium transition-all",
    94→                "focus:ring-ring focus:ring-2 focus:ring-offset-2 focus:outline-none",
    95→                "disabled:cursor-not-allowed disabled:opacity-50",
    96→                isSelected
    97→                  ? "bg-primary text-primary-foreground shadow-sm"
    98→                  : "bg-muted text-muted-foreground hover:bg-muted/80",
    99→              )}
   100→            >
   101→              {getLabel(tag)}
   102→            </button>
   103→          );
   104→        })}
   105→      </div>
   106→    </div>
   107→  );
   108→}
