   162→export function SideEffectsSelector({
   163→  selectedTags,
   164→  onChange,
   165→  disabled = false,
   166→  className,
   167→}: {
   168→  selectedTags: SideEffect[];
   169→  onChange: (tags: SideEffect[]) => void;
   170→  disabled?: boolean;
   171→  className?: string;
   172→}) {
