   200→export type PeriodSelectorProps = {
   201→  /** Currently selected period */
   202→  value: "7" | "30" | "90";
   203→  /** Callback when period changes */
   204→  onChange: (value: "7" | "30" | "90") => void;
   205→  /** Labels for each period (defaults to French) */
   206→  labels?: {
   207→    "7": string;
   208→    "30": string;
   209→    "90": string;
