   234→}: PeriodSelectorProps) {
   235→  const periods: ("7" | "30" | "90")[] = ["7", "30", "90"];
   236→
   237→  return (
   238→    <div
   239→      className={cn("bg-muted inline-flex rounded-lg p-1", className)}
   240→      role="tablist"
   241→    >
   242→      {periods.map((period) => (
   243→        <button
   244→          key={period}
   245→          type="button"
   246→          role="tab"
   247→          aria-selected={value === period}
   248→          onClick={() => onChange(period)}
   249→          className={cn(
   250→            "rounded-md px-4 py-2 text-sm font-medium transition-all",
   251→            "focus:ring-ring focus:ring-2 focus:ring-offset-2 focus:outline-none",
   252→            value === period
   253→              ? "bg-background text-foreground shadow-sm"
   254→              : "text-muted-foreground hover:text-foreground",
   255→          )}
   256→        >
   257→          {labels[period]}
   258→        </button>
   259→      ))}
   260→    </div>
   261→  );
   262→}
