    12→export type TimelineEntryProps = {
    13→  /** Date of the entry */
    14→  date: string;
    15→  /** Mood value (-3 to +3) */
    16→  mood: MoodValueBipolar;
    17→  /** Sleep information */
    18→  sleep?: {
    19→    hours: number;
    20→    quality?: "bad" | "average" | "good";
    21→  };
    22→  /** Context tags */
    23→  tags?: string[];
    24→  /** Whether the entry is clickable */
    25→  onClick?: () => void;
    26→  /** Additional CSS classes */
    27→  className?: string;
    28→};
    29→
    30→/**
    31→ * TimelineEntry Component
    32→ *
    33→ * Displays a single mood entry in a timeline list.
    34→ * Shows mood indicator, date, sleep info, and tags.
    35→ *
    36→ * @example
    37→ * ```tsx
    38→ * <TimelineEntry
    39→ *   date="lundi 15 janvier"
    40→ *   mood={2}
    41→ *   sleep={{ hours: 7.5 }}
    42→ *   tags={['Sport']}
    43→ *   onClick={() => openEntry(id)}
    44→ * />
    45→ * ```
    46→ */
    47→export function TimelineEntry({
    48→  date,
    49→  mood,
    50→  sleep,
    51→  tags,
    52→  onClick,
    53→  className,
    54→}: TimelineEntryProps) {
    55→  const displayMood = mood > 0 ? `+${mood}` : String(mood);
    56→  const moodLabel = moodBipolarLabels[mood];
    57→
    58→  return (
    59→    <Card
    60→      className={cn(
    61→        "transition-all",
    62→        onClick && "cursor-pointer hover:shadow-md",
    63→        className,
    64→      )}
    65→      onClick={onClick}
    66→    >
    67→      <CardContent className="flex items-center gap-4 p-4">
    68→        {/* Mood indicator */}
    69→        <div
    70→          className="flex size-12 shrink-0 items-center justify-center rounded-full text-lg font-bold text-white shadow-sm"
    71→          style={{ backgroundColor: getMoodBipolarColor(mood) }}
    72→        >
    73→          {displayMood}
    74→        </div>
    75→
    76→        {/* Content */}
    77→        <div className="flex min-w-0 flex-1 flex-col gap-1">
    78→          <span className="text-foreground font-medium">{date}</span>
    79→          <div className="text-muted-foreground flex items-center gap-2 text-sm">
    80→            <span>{moodLabel}</span>
    81→            {sleep && (
    82→              <>
    83→                <span className="text-muted-foreground/50">·</span>
    84→                <span>{sleep.hours}h sommeil</span>
    85→              </>
    86→            )}
    87→          </div>
    88→          {tags && tags.length > 0 && (
    89→            <div className="mt-1 flex flex-wrap gap-1">
    90→              {tags.map((tag) => (
    91→                <span
    92→                  key={tag}
    93→                  className="bg-muted text-muted-foreground rounded-full px-2 py-0.5 text-xs"
    94→                >
    95→                  {tag}
    96→                </span>
    97→              ))}
    98→            </div>
    99→          )}
   100→        </div>
   101→
   102→        {/* Arrow */}
   103→        {onClick && (
   104→          <ChevronRight className="text-muted-foreground size-5 shrink-0" />
