   111→export type MoodChartData = {
   112→  date: string;
   113→  mood: MoodValueBipolar | null;
   114→};
   115→
   116→export type MoodChartProps = {
   117→  /** Chart data points */
   118→  data: MoodChartData[];
   119→  /** Chart height in pixels */
   120→  height?: number;
   121→  /** Additional CSS classes */
   122→  className?: string;
   123→};
   124→
   125→/**
   126→ * MoodChart Component
   127→ *
   128→ * Simple bar chart showing mood evolution over time.
   129→ * Each bar is colored based on the mood value.
   130→ *
   131→ * @example
   132→ * ```tsx
   133→ * <MoodChart
   134→ *   data={[
   135→ *     { date: '15', mood: 2 },
   136→ *     { date: '14', mood: 1 },
   137→ *     { date: '13', mood: 0 },
   138→ *   ]}
   139→ * />
   140→ * ```
   141→ */
   142→export function MoodChart({ data, height = 150, className }: MoodChartProps) {
   143→  // Map mood (-3 to +3) to height percentage (0 to 100)
   144→  const getBarHeight = (mood: MoodValueBipolar) => {
   145→    // Convert -3 to +3 to 0 to 100
   146→    return ((mood + 3) / 6) * 100;
   147→  };
   148→
   149→  return (
   150→    <div className={cn("flex flex-col gap-2", className)}>
   151→      <div
   152→        className="bg-muted/50 flex items-end justify-between gap-1 rounded-lg p-4"
   153→        style={{ height }}
   154→      >
   155→        {data.map((entry, index) => (
   156→          <div key={index} className="flex flex-1 flex-col items-center gap-1">
   157→            {entry.mood !== null ? (
   158→              <div
   159→                className="w-full max-w-8 rounded-t-sm transition-all"
   160→                style={{
   161→                  height: `${getBarHeight(entry.mood)}%`,
   162→                  backgroundColor: getMoodBipolarColor(entry.mood),
   163→                  minHeight: "8px",
   164→                }}
   165→              />
   166→            ) : (
   167→              <div className="bg-muted h-2 w-full max-w-8 rounded-t-sm" />
   168→            )}
   169→          </div>
   170→        ))}
   171→      </div>
   172→
   173→      {/* X-axis labels */}
   174→      <div className="flex justify-between px-4">
   175→        {data.map((entry, index) => (
   176→          <span
   177→            key={index}
   178→            className="text-muted-foreground flex-1 text-center text-xs"
   179→          >
   180→            {entry.date}
   181→          </span>
   182→        ))}
   183→      </div>
   184→
   185→      {/* Y-axis legend */}
   186→      <div className="flex justify-between px-4">
   187→        <span className="text-muted-foreground text-xs">Très bas (-3)</span>
   188→        <span className="text-muted-foreground text-xs">Stable (0)</span>
   189→        <span className="text-muted-foreground text-xs">Très élevé (+3)</span>
   190→      </div>
   191→    </div>
   192→  );
   193→}
